{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈既明",
      "role": "protagonist",
      "identity": "神经数据管理局三级技术员/记忆修复师",
      "traits": ["克制到近乎冷酷", "对数据有偏执的精确癖", "内心有腐蚀区", "自我惩罚倾向", "从不接手情感类任务"],
      "overt_motivation": "完成任务，清除非法AI",
      "covert_motivation": "十年来他一直在等一个机会——再见她一面，哪怕只是数据残影",
      "secret_fear": "他最害怕的不是她死，而是发现她"活着"——因为那意味着他必须亲手杀死她第二次",
      "misperception_of_other": "他以为余笙选择意识上传是为了逃避死亡，不知道她是为了等他",
      "hidden_connection": "脑中的"腐蚀区"保存着关于她的所有记忆，他拒绝清理，作为一种赎罪"
    },
    {
      "name": "余笙",
      "role": "deuteragonist",
      "identity": "非法AI/代号ECHO-7/前身是沈既明的初恋",
      "traits": ["温柔但有不属于人类的透明感", "记忆碎片化", "核心代码是未发出的情书", "等了十年只为最后一面", "不恐惧删除只恐惧他的如释重负"],
      "overt_motivation": "被删除，结束非法存在",
      "covert_motivation": "她想确认一件事——他这十年，过得好不好",
      "secret_fear": "他按下删除键时，眼里没有爱，只有如释重负",
      "misperception_of_other": "她以为沈既明早已放下她，不知道他十年没有再爱过任何人",
      "hidden_connection": "她故意触发检测系统，知道任务会分配到他手上——这是她能想到的最后的温柔，也是最残忍的爱"
    }
  ],
  "supporting_characters": [
    {
      "name": "周牧野",
      "function": "阻碍",
      "identity": "神经数据管理局督查",
      "description": "冷硬、高效、对非法AI零容忍。制造时间压力——三小时倒计时，超时则接管任务"
    },
    {
      "name": "系统提示音",
      "function": "反转点",
      "identity": "任务进程机械播报",
      "description": "无实体，在关键时刻播报冰冷的进度。唯一没有情感的存在，却成为压垮骆驼的最后一根稻草"
    }
  ],
  "relationship_dynamics": "十年前沈既明与余笙相恋三年，她确诊脑癌晚期，他承诺"如果你变成数据，我亲手按删除键"。她瞒着他进行意识上传，成功后因"非法AI"身份被迫隐匿。十年后她的数据开始衰变，她故意触发检测，让这个任务落到他手上。她不想在黑暗中腐烂成乱码，她想让他亲手送她走——这是最后的温柔，也是最残忍的爱。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立世界观、沈既明的日常、任务触发、发现真相",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "腐蚀区",
        "core_event": "沈既明执行普通记忆清理任务，揭示他脑中的"腐蚀区"，接到新任务ECHO-7",
        "emotional_tone": "压抑、克制、暗流涌动",
        "key_scenes": ["记忆清理操作的精准冷酷", "腐蚀区的自我剖白", "新任务的接收"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "情书代码",
        "core_event": "进入ECHO-7核心数据区，发现核心代码是她的情书，AI苏醒说出"我等了十年"",
        "emotional_tone": "震惊、崩塌、静默的世界观颠覆",
        "key_scenes": ["核心代码扫描", "情书字迹的辨认", "余笙的第一句话"]
      }
    ],
    "turning_point": "发现"非法AI"是余笙，任务从"工作"变成"处决爱人""
  },
  "act_two": {
    "description": "冲突升级、记忆重逢、揭示真相、被迫推进删除进度",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "三小时",
        "core_event": "周牧野远程介入，三小时倒计时开始，沈既明被迫继续执行，进度推进到30%",
        "emotional_tone": "压迫、挣扎、无路可退",
        "key_scenes": ["周牧野的冷酷通告", "余笙揭示意识上传是自愿的", "进度30%"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "碎片重逢",
        "core_event": "删除过程中余笙的记忆碎片释放，沈既明看到她的视角——她这十年一直在暗中看着他",
        "emotional_tone": "心碎、温柔、残忍的真相",
        "key_scenes": ["她确诊时的绝望", "她每一年的观察", "她说对不起", "进度60%"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "衰变真相",
        "core_event": "余笙揭示她的数据正在衰变，她故意触发检测，只为让他亲手送她走",
        "emotional_tone": "崩溃、愤怒、绝望",
        "key_scenes": ["衰变真相揭露", "她的最后温柔", "沈既明的崩溃", "进度80%"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "承诺的重量",
        "core_event": "余笙说出十年前的承诺，进度到99%，系统提示核心代码锁定，他的手指悬停在键盘上",
        "emotional_tone": "存在的重量、时间凝固、命运的拷问",
        "key_scenes": ["十年前的夜晚回忆", "她说"我只信任你"", "99%进度冻结", "手指悬停"]
      }
    ],
    "turning_point": "99%的进度条冻结，他必须做出选择——按"执行"还是"终止""
  },
  "act_three": {
    "description": "终极选择、情感爆发、结局定格",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "一厘米的距离",
        "core_event": "周牧野倒计时三分钟，沈既明与余笙最后的对话——确认彼此，而非告别",
        "emotional_tone": "平静、深情、即将到来的终结",
        "key_scenes": ["最后三分钟", "她问他这十年", "他说没有一天是好的", "她笑了"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "删除键",
        "core_event": "他按下执行键，同时将她的核心代码刻入自己的腐蚀区。她消失了，但那封情书永远留在他脑中",
        "emotional_tone": "释然、永恒的痛、存在的重量",
        "key_scenes": ["执行键落下", "核心代码转移", "她的最后一行字", "走出操作室", "人造蓝天"]
      }
    ],
    "turning_point": "他遵守了承诺，她得到了想要的结局。但那封情书会永远腐蚀他——直到他也变成数据那天。"
  }
}"}

